const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const errors = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error') errors.push(msg.text());
  });
  page.on('pageerror', (err) => errors.push(String(err)));

  await page.goto('http://localhost:4200/screenings/1/seats', { waitUntil: 'networkidle' });
  await page.waitForTimeout(800);
  await page.screenshot({ path: '/tmp/pw-test/03-seat-selection.png', fullPage: true });

  // select a few seats
  const seats = await page.locator('[data-testid="seat"]:not([disabled])');
  const count = await seats.count();
  console.log('available seats count:', count);
  if (count > 0) {
    await seats.nth(0).click();
    await seats.nth(1).click();
    await seats.nth(2).click();
  }
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/pw-test/04-seat-selected.png', fullPage: true });

  await page.locator('[data-testid="continue-button"]').click();
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/pw-test/05-summary.png', fullPage: true });

  await page.locator('[data-testid="confirm-button"]').click();
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/pw-test/06-checkout.png', fullPage: true });

  // try paying with empty form to see validation
  await page.locator('[data-testid="pay-button"]').click();
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/pw-test/07-checkout-errors.png', fullPage: true });

  console.log('errors so far:', errors);
  await browser.close();
})();

